    printf("Running unit_test_quickSort_unsorted_array_normal...
");

    int unsorted_vals[6] = {5, 2, 9, 1, 5, 6}; // Unsorted input values
    int size = 6; // Array size
    int* input_array = NULL; // Array to be sorted
    int* expected_sorted_array = NULL; // Expected sorted array

    input_array = create_int_test_array(unsorted_vals, size);
    expected_sorted_array = helper_copy_int_array(unsorted_vals, size);

    quickSort(input_array, 0, size - 1);
    quickSort(expected_sorted_array, 0, size - 1);
    assert_array_sorted(input_array, size);
    assert_array_equal(input_array, expected_sorted_array, size);

    cleanup_int_test_array(input_array);
    cleanup_int_test_array(expected_sorted_array);

    printf("unit_test_quickSort_unsorted_array_normal passed.
");
}

int main() {
    printf("Starting all generated unit tests...

");
    unit_test_quickSort_unsorted_array_normal();
    printf("All generated tests completed successfully!
");
    return 0;
}


