// Function: assert_array_equal (from helper pool)
void assert_array_equal(const int *actual, const int *expected, int size)
{
    /*
    Assert that two arrays are equal.
    */
    assert(actual != NULL && expected != NULL);
    assert(size > 0);
    for (int i = 0; i < size; ++i)
    {
        assert(actual[i] == expected[i]);
    }
}

// Function: assert_array_sorted (from helper pool)
void assert_array_sorted(const int *actual_array, int size)
{
    /*
    Assert that the array is sorted in non-decreasing order.
    */
    assert(actual_array != NULL);
    for (int i = 0; i < size - 1; ++i)
    {
        assert(actual_array[i] <= actual_array[i + 1]);
    }
}

// Function: assert_int_equal (from helper pool)
void assert_int_equal(int actual, int expected) {
    /*
    Assert that two int values are equal.
    */
    if (actual != expected) {
        printf("Assertion failed: expected %d, but got %d
", expected, actual);
        assert(actual == expected);
    }
}

// ========== Searched From Pool - Utility Operations ==========

// Function: create_int_test_array (from helper pool)
int* create_int_test_array(const int *values, int size)
{
    int *array = malloc(size * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed
");
        exit(1);
    }
    for (int i = 0; i < size; i++) {
        array[i] = values[i];
    }
    return array;
}

// Function: reset_int_test_array (from helper pool)
void reset_int_test_array(int *array, int size)
{
    /*
    Reset the contents of an array to zero.
    */
    memset(array, 0, size * sizeof(int));
}

// Function: cleanup_int_test_array (from helper pool)
void cleanup_int_test_array(int *array)
{
    /*
    Free the memory allocated for an array.
    */
    free(array);
}

// ========== Created - Utility Operations ==========

// Creates a deep copy of an integer array of given size. The returned array must be freed by the caller.
int *helper_copy_int_array(const int *src, int size) {
    if (size <= 0 || src == NULL) return NULL;
    int *copy = (int *)malloc(size * sizeof(int));
    if (!copy) return NULL;
    for (int i = 0; i < size; ++i) {
        copy[i] = src[i];
    }
    return copy;
}


